import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        while (n-- > 0) {
            int p = sc.nextInt();
            int[] dayLengths = new int[p];
            int[] currentHours = new int[p];
            int[][] volumes = new int[p][];
            int maxDay = 0;

            for (int i = 0; i < p; i++) {
                int d = sc.nextInt();
                int h = sc.nextInt();
                dayLengths[i] = d;
                currentHours[i] = h;
                volumes[i] = new int[d];
                for (int j = 0; j < d; j++) {
                    volumes[i][j] = sc.nextInt();
                }
                maxDay = Math.max(maxDay, d);
            }

            // We'll consider up to LCM of all day lengths in minutes, but cap at maxDay * 60 * 2 for safety
            int totalMinutes = maxDay * 60;
            // Find LCM of day lengths in minutes
            long lcm = 1;
            for (int d : dayLengths) {
                lcm = lcm(lcm, d * 60L);
                if (lcm > 1000000) {
                    lcm = maxDay * 60L;
                    break;
                }
            }
            totalMinutes = (int) lcm;

            int[] accessPerMinute = new int[totalMinutes];

            for (int planet = 0; planet < p; planet++) {
                int d = dayLengths[planet];
                int h = currentHours[planet];
                int dayMinutes = d * 60;
                int startOffset = (h * 60) % dayMinutes;

                for (int hourIdx = 0; hourIdx < d; hourIdx++) {
                    int globalStart = (startOffset + hourIdx * 60) % dayMinutes;
                    int vol = volumes[planet][hourIdx];
                    for (int t = 0; t < 60; t++) {
                        int minute = (globalStart + t) % dayMinutes;
                        if (minute < totalMinutes) {
                            accessPerMinute[minute] += vol;
                        }
                    }
                }
            }

            // Sliding window max over 60 minutes
            long windowSum = 0;
            for (int i = 0; i < 60 && i < totalMinutes; i++) {
                windowSum += accessPerMinute[i];
            }
            long maxVolume = windowSum;
            for (int i = 60; i < totalMinutes; i++) {
                windowSum += accessPerMinute[i] - accessPerMinute[i - 60];
                if (windowSum > maxVolume) {
                    maxVolume = windowSum;
                }
            }

            System.out.println(maxVolume);
        }
        sc.close();
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int datasets = Integer.parseInt(first);
        StringBuilder out = new StringBuilder();

        for (int tc = 0; tc < datasets; tc++) {
            int n = fs.nextInt();
            int maxVolume = Integer.MIN_VALUE;

            for (int i = 0; i < n; i++) {
                int dayLength = fs.nextInt();
                fs.nextInt(); // current time, not needed for maximum search

                for (int h = 0; h < dayLength; h++) {
                    int volume = fs.nextInt();
                    if (volume > maxVolume) maxVolume = volume;
                }
            }

            out.append(maxVolume).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            n = int(next(it))
        except StopIteration:
            break

        if n == 0:
            break

        best = -10**18

        for _ in range(n):
            d = int(next(it))          # length of day
            _ = next(it)               # current time, not needed for maximum
            for _ in range(d):
                v = int(next(it))
                if v > best:
                    best = v

        out.append(str(best))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
